"""Islamiat (Ikhtiari) XII PDF90: pp.170–171 — astronomy (end); mathematics; agriculture; naval science; 2. Andalus. Run: python class12_iski_page090.py"""
from class12_iski_common import BOOK, Builder, rec, P


def p90():
    b = Builder()
    P(b, [('… into which they are transferred, so that any observer, from any place on the surface of the earth, can observe the celestial bodies with as much ease and accuracy as possible and determine their position. Moreover with its help such instruments are invented and used which give as much guarantee as possible of the correctness of our observations!', 'میں منتقل کر لیا جاتا ہے تاکہ کوئی شمار کنندہ سطحِ زمین پر کسی جگہ سے حتی الامکان سہولت اور صحت کے ساتھ اجرامِ فلکی کا مشاہدہ کر کے اس کے مقام کو متعین کر سکے۔ نیز اس کی مدد سے ایسے آلات کو ایجاد اور استعمال کیا جاتا ہے جو ہمارے مشاہدات کی درستگی کی زیادہ سے زیادہ ضمانت دے سکیں!', '… ته لېږدول کېږي، تر څو هر شمېرونکی د ځمکې د سطحې له هر ځای څخه په ممکنه اسانۍ او سموالي سره د آسماني اجسامو کتنه وکړي او ځای یې وټاکي. همداسې د هغه په مرسته داسې آلې ایجادېږي او کارول کېږي چې زموږ د کتنو د سموالي تر ډېره ډېر تضمین ورکړي!'),
          ('The Arabs had some knowledge in \'ilm al-hay\'ah. In the era of the Banu Abbas an institution was established by the name of "Dar al-Hikmah". In it Greek books were translated into Arabic. Among them there were many books on astronomy too. Besides this, Muslims built observatories for practical experiments and observations and wrote many books. Among them Ya\'qub bin Tariq wrote Zij Mahlul fi al-Sindhind li-Daraja Daraja, and Ahmad bin Kathir al-Farghani wrote books by the name of Kitab al-\'Ilal and Tarkib al-Aflak. \'Umar Ibn al-Farrukhan al-Tabari, Yahya bin Abi Mansur, Muhammad bin Musa al-Khwarizmi, al-Farghani, Habash al-Hasib, al-Kindi, al-Battani etc. are included. Besides them too there is a long list of those who, by working in astronomy, left a precious treasure for coming generations.', 'عرب علم ہیئت میں قدرے معلومات رکھتے تھے۔ بنو عباس کے عہد میں ”دار الحکمت“ کے نام سے ایک ادارہ قائم ہوا تھا۔ اس میں یونانی کتابوں کو عربی میں منتقل کیا گیا تھا۔ ان میں علم فلکیات کی بھی بہت سی کتابیں تھیں۔ اس کے علاوہ مسلمانوں نے عملی تجربات و مشاہدات کے لیے رصد گاہیں بنائیں اور بہت سی کتابیں تحریر کیں۔ جن میں یعقوب بن طارق نے زیج محلول فی السند ہند للدرجۃ درجۃ، احمد بن کثیر الفرغانی، کتاب العلل اور ترکیب الافلاک کے نام سے کتابیں تحریر کیں۔ عمر ابن الفرخان الطبری، یحییٰ بن ابی منصور، محمد بن موسیٰ الخوارزمی، الفرغانی، حبش الحاسب، الکندی، البتانی، وغیرہ شامل ہیں۔ ان کے علاوہ بھی ایک طویل فہرست ہے۔ جنہوں نے علم فلکیات میں کام کر کے آنے والی نسلوں کے لیے قیمتی ذخیرہ چھوڑا ہے۔', 'عربانو په علم الهیئت کې یو څه معلومات درلودل. د بنو عباس په دوره کې د «دار الحکمه» په نوم یوه اداره جوړه شوې وه، چې په کې یوناني کتابونه عربي ته ژباړل شوي وو؛ په هغو کې د نجومو ډېر کتابونه هم وو. سربېره پر دې مسلمانانو د عملي تجربو او کتنو لپاره رصدخانې جوړې کړې او ډېر کتابونه یې ولیکل. په هغو کې یعقوب بن طارق «زیج محلول فی السندهند للدرجة درجة» ولیکه، او احمد بن کثیر الفرغاني د «کتاب العلل» او «ترکیب الافلاک» په نوم کتابونه ولیکل. عمر ابن الفرخان الطبري، یحیی بن ابي منصور، محمد بن موسی الخوارزمي، الفرغاني، حبش الحاسب، الکندي، البتاني او نور پکې شامل دي. له دوی پرته هم یو اوږد لېست شته چې په نجومو کې یې کار وکړ او راتلونکو نسلونو ته یې قیمتي زېرمه پرېښوده.')])
    b.h('Mathematics', 'علم ریاضیات', 'ریاضي')
    P(b, [('Muslims made great progress in mathematics like in other sciences, and bringing their abilities into use accomplished such feats whose example is not found till today. Not only Muslims but the whole world benefits from them. Before Muslims, the science of all numbers and figures was called riyadi (mathematics). But Muslims for the first time divided it into 4 kinds and gave separate names, which are called \'Ilm al-Hisab (arithmetic), \'Ilm Handasah (geometry), \'Ilm al-Jabr wa al-Muqabalah (algebra) and Geometry.', 'مسلمانوں نے علم ریاضی میں دیگر علوم کی طرح بہت ترقی کی اور اپنی صلاحیتوں کو بروئے کار لا کر ایسے ایسے کارنامے سرانجام دیے جن کی مثال آج تک نہیں ملتی۔ نہ صرف مسلمان بلکہ پوری دنیا ان سے استفادہ کرتی ہے۔ مسلمانوں سے پہلے تمام اعداد و اشکال کے علم کو ریاضی کہا جاتا تھا۔ مگر مسلمانوں نے پہلی دفعہ اسے 4 اقسام میں تقسیم کر کے علیحدہ علیحدہ نام دیے جسے علم الحساب، علم ہندسہ، علم جبر و المقابلہ اور علم جیومیٹری کہا جاتا ہے۔', 'مسلمانانو د نورو علومو په څېر په ریاضي کې ډېر پرمختګ وکړ، او خپلې وړتیاوې یې په کار واچولې او داسې کارنامې یې سرته ورسولې چې بېلګه یې تر نن نه موندل کېږي. نه یوازې مسلمانان بلکې ټوله نړۍ ترې ګټه اخلي. له مسلمانانو مخکې د ټولو عددونو او شکلونو علم ته ریاضي ویل کېده. خو مسلمانانو لومړی ځل هغه په ۴ ډولونو ووېشه او جلا جلا نومونه یې ورکړل، چې د حساب علم، د هندسې علم، د جبر او مقابلې علم، او د جیومیټرۍ علم بلل کېږي.'),
          ('The initial work in mathematics was done by translating from the Greeks; later Muslims wrote many books in it on the basis of observations and experiments, in which they wrote the principles and rules of all the branches of mathematics.', 'ریاضی میں ابتدائی کام یونانیوں کے ترجمے کرنے سے ہوا بعد میں مسلمانوں نے اس میں مشاہدوں اور تجربوں کی بنیاد پر بہت سی کتابیں لکھیں جن میں ریاضی کی تمام شاخوں کے اصول و ضوابط تحریر کیے۔', 'په ریاضي کې لومړنی کار د یونانیانو له ژباړې پیل شو؛ وروسته مسلمانانو په کې د کتنو او تجربو پر بنسټ ډېر کتابونه ولیکل، چې په هغو کې یې د ریاضي د ټولو څانګو اصول او ضوابط ولیکل.'),
          ('The history of the mathematics of Muslims in fact begins from Muhammad bin Musa al-Khwarizmi. His famous book is "al-Mukhtasar fi Hisab al-Jabr wa al-Muqabalah". Al-Kindi was the first mathematician who wrote regular comprehensive treatises on approximately all the branches of mathematics. After him his student Ahmad Sarakhsi was the best mathematician of his era. Besides them, the names of Musa Khwarizmi, al-Farghani, Habash al-Hasib, Ibn al-Haytham, al-Biruni, \'Umar Khayyam, Sharif al-Din bin Tusi, Nasir al-Din Tusi, al-Shirazi etc. are worth mentioning.', 'مسلمانوں کی ریاضی کی تاریخ درحقیقت محمد بن موسیٰ الخوارزمی سے شروع ہوتی ہے۔ اس کی مشہور کتاب ”المختصر فی حساب الجبر والمقابلہ“ ہے۔ الکندی پہلا ریاضی دان تھا جس نے ریاضی کی تقریباً تمام شاخوں پر باقاعدہ جامع رسالے لکھے۔ اس کے بعد اس کا شاگرد احمد سرخسی اپنے دور کا بہترین ریاضی دان تھا۔ ان کے علاوہ موسیٰ خوارزمی، الفرغانی، حبش الحاسب، ابن الہیثم، البیرونی، عمر خیام، شریف الدین بن طوسی، نصیر الدین طوسی، الشیرازی وغیرہ کے نام قابلِ ذکر ہیں۔', 'د مسلمانانو د ریاضي تاریخ په اصل کې له محمد بن موسی الخوارزمي پیل کېږي. مشهور کتاب یې «المختصر في حساب الجبر والمقابله» دی. الکندي لومړنی ریاضي‌پوه و چې د ریاضي نږدې پر ټولو څانګو یې منظمې جامع رسالې ولیکلې. له هغه وروسته یې شاګرد احمد سرخسي د خپلې دورې غوره ریاضي‌پوه و. له دوی پرته د موسی خوارزمي، الفرغاني، حبش الحاسب، ابن الهیثم، البیروني، عمر خیام، شریف الدین بن طوسي، نصیرالدین طوسي، الشیرازي او نورو نومونه د یادونې وړ دي.')])
    r1 = rec(b, 3, 170, 90, [170])
    t = Builder()
    t.h('Agriculture (\'Ilm al-Zira\'ah)', 'علم الزراعۃ', 'کرنه (علم الزراعه)')
    t.p('In \'ilm al-zira\'ah come cultivation, farming, gardening etc. In English it is called (Agriculture). Muslims worked on many topics in agriculture and farming, and wrote books, treatises and articles, among which horticulture, vegetables, crops, beekeeping, animal husbandry, poultry, irrigation, the preservation of grain, information related to land, and the system of landholding etc. are included. In Granada the important author of agriculture was Muhammad bin Malik al-Tighnari.', 'علم الزراعت میں کاشتکاری و کھیتی باڑی وغیرہ آتا ہے۔ اسے انگریزی میں (Agriculture) کہا جاتا ہے۔ مسلمانوں نے زراعت و فلاحت میں بہت سے موضوعات پر کام کیا اور کتابیں، رسالے اور مقالے لکھے۔ جن میں باغبانی، سبزیات، فصلیں، شہد کی مکھیاں پالنا، پرورشِ حیوانات، مرغبانی، آبپاشی، تحفظِ اناج، زمین سے متعلق معلومات اور نظامِ زمینداری وغیرہ شامل ہیں۔ غرناطہ میں علم الزراعۃ کا اہم مصنف محمد بن مالک الطغری تھا۔', 'په علم الزراعه کې کرنه، کښت او نور راځي. په انګلیسي کې ورته (Agriculture) وايي. مسلمانانو په کرنه او فلاحت کې پر ډېرو موضوعګانو کار وکړ او کتابونه، رسالې او مقالې یې ولیکلې، چې په کې باغواني، سبزیجات، فصلونه، د شاتو مچیو روزنه، د څارویو روزنه، چرګ‌روزنه، اوبه‌لګول، د غلو ساتنه، د ځمکې اړوند معلومات او د زمیندارۍ نظام او نور شامل دي. په غرناطه کې د کرنې مهم لیکوال محمد بن مالک الطغري (طغنري) و.')
    t.h('Naval science (\'Ilm al-Bihar)', 'علم البحار', 'سمندري علوم (علم البحار)')
    t.p('In the first century Hijri, in the era of Hazrat Uthman Ghani (may Allah be pleased with him), Hazrat Amir Mu\'awiyah (may Allah be pleased with him) prepared the first naval fleet. Musa bin Nusayr (may Allah be pleased with him) established a shipbuilding factory in Tunis, in which ships were prepared for the protection of Africa and the lands of the Maghrib. The historian of the history of Islamic civilisation, Jurji Zaydan, writes that in the era of the Fatimids, in the Egyptian port of Alexandria and in Damietta, there were very large numbers of warships and a very large naval force. The first factory in Egypt in which warships were built was established on the island of Rawdah in 154 AH. In the same way al-Mu\'izz al-Din Fatimi built a Dar al-Sina\'ah in which six hundred warships were built. In the era of the Banu Abbas, immense work was done for the progress of maritime communications and shipbuilding. Because of naval warfare, Constantinople was conquered in 1453. Muslims had built various kinds of ships for transporting various things — for example the "Faridah" for loading horses, and in the "Hammalah" grain was transported. The "Ghurab" was a fighting ship. Just as Muslims accomplished services in other sciences, in the same way Muslims made great progress in naval science too.', 'پہلی صدی ہجری میں حضرت عثمان غنی رضی اللہ عنہ کے عہد میں حضرت امیر معاویہ رضی اللہ عنہ نے پہلا بحری بیڑا تیار کیا۔ موسیٰ بن نصیر رضی اللہ عنہ نے تیونس میں جہاز سازی کا کارخانہ قائم کیا۔ جس میں افریقہ اور بلادِ مغرب کی حفاظت کے لیے جہاز تیار ہوتے تھے۔ تاریخ تمدنِ اسلام کے مورخ جرجی زیدان لکھتے ہیں کہ فاطمیوں کے عہد میں مصر کی بندرگاہ سکندریہ اور دمیاط میں بہت زیادہ تعداد میں جنگی جہاز اور بہت بڑی سمندری فوج تھی۔ مصر میں پہلا کارخانہ جس میں جنگی جہاز تیار ہوتے تھے جزیرہ دومنہ میں 154ھ میں قائم ہوا تھا۔ اسی طرح معز الدین فاطمی نے ایک دار الصناعۃ بنایا۔ جس میں چھ سو جنگی جہاز تیار ہوتے تھے۔ بنی عباس کے دور میں سمندری مواصلات کی ترقی اور جہاز بنانے کے لیے بے انتہا کام ہوا۔ بحری جنگ کی وجہ سے ہی 1453ء میں قسطنطنیہ فتح ہوا۔ مسلمانوں نے مختلف چیزوں کی بار برداری کے لیے مختلف قسم کے سمندری جہاز بنا رکھے تھے۔ مثلاً ”فریدہ“ گھوڑوں کو لادنے کے لئے ”حمالہ“ میں غلہ کی بار برداری کی جاتی تھی۔ ”غراب“ لڑاکا جہاز تھا۔ جس طرح دیگر علوم میں مسلمانوں نے خدمات سرانجام دیں ایسے ہی علم البحار میں بھی مسلمانوں نے خوب ترقی کی۔', 'په لومړۍ هجري پېړۍ کې د حضرت عثمان غني رضي الله عنه په دوره کې حضرت امیر معاویه رضي الله عنه لومړنی سمندري بېړی جوړ کړ. موسی بن نصیر رضي الله عنه په تونس کې د کښتۍ جوړولو کارخانه جوړه کړه، چې په کې د افریقې او مغرب هېوادونو د ساتنې لپاره کښتۍ جوړېدې. د اسلامي تمدن د تاریخ مورخ جرجي زیدان لیکي چې د فاطمیانو په دوره کې د مصر په اسکندریه بندر او دمیاط کې ډېر شمېر جنګي کښتۍ او ډېر لوی سمندري پوځ و. په مصر کې لومړنۍ کارخانه چې جنګي کښتۍ پکې جوړېدې، په ۱۵۴ هجري کې د «دومنه» (روضه) په ټاپو کې جوړه شوې وه. همداسې معز الدین فاطمي یو دار الصناعه جوړ کړ چې شپږ سوه جنګي کښتۍ پکې جوړېدې. د بني عباس په دوره کې د سمندري مخابراتو د پرمختګ او کښتۍ جوړولو لپاره بې‌حده کار وشو. د سمندري جګړې له امله په ۱۴۵۳ع کې قسطنطنیه فتح شوه. مسلمانانو د بېلابېلو شیانو د لېږد لپاره بېلابېل ډوله سمندري کښتۍ جوړې کړې وې؛ لکه «فریده» د اسونو د بارولو لپاره، په «حماله» کې د غلې لېږد کېده، او «غراب» جنګي کښتۍ وه. لکه څنګه چې مسلمانانو په نورو علومو کې خدمتونه سرته ورسول، همداسې یې په سمندري علومو کې هم ښه پرمختګ وکړ.')
    t.h('2. Progress, services and influences of the sciences in Andalus (Spain):', '2۔ اندلس (سپین) میں علوم کی ترقی، خدمات اور اثرات:', '۲. په اندلس (هسپانیه) کې د علومو پرمختګ، خدمتونه او اغېزې')
    t.p('The Islamic state whose foundation the Noble Prophet ﷺ laid in Madinah Munawwarah had become considerably vast in the era of the Rightly-Guided Caliphs itself. In the era of the Banu Umayyah the series of conquests became even more extensive, and the Islamic state went out beyond the borders of the Arabian Peninsula. The eye of the heavens saw that era too when the land of Andalus too became part of the Islamic state.', 'نبی اکرم صلی اللہ علیہ وآلہٖ وسلم نے جس اسلامی ریاست کی بنیاد مدینہ منورہ میں رکھی وہ خلفائے راشدین کے عہد میں ہی خاصی وسیع ہو گئی تھی۔ بنو امیہ کے دور میں فتوحات کا سلسلہ مزید وسیع ہو گیا اور اسلامی ریاست جزیرہ نمائے عرب کی حدود سے باہر نکل گئی۔ چشمِ فلک نے وہ دور بھی دیکھا جب اندلس کی سرزمین بھی اسلامی ریاست کا حصہ بن گئی۔', 'نبي اکرم ﷺ چې د کوم اسلامي دولت بنسټ په مدینه منوره کې کېښود، هغه د خلفای راشدینو په دوره کې ښه پراخ شوی و. د بنو امیه په دوره کې د فتوحاتو لړۍ لا پراخه شوه، او اسلامي دولت د عربو ټاپووزمې له پولو بهر ووت. د آسمان سترګې هغه دوره هم ولیده چې د اندلس خاوره هم د اسلامي دولت برخه شوه.')
